import "../styles/Projects.css";
import telo_chat from "../assets/telo-chat.png";
import notes from "../assets/notes.jpg";
import telo_main from "../assets/telo-main.png";

function Projects() {
  return (
    <div className="projects-container">
      <h3>WHAT I'VE BUILT</h3>
      <h1>My Projects</h1>
      <div className="projects-card-container">
        <div className="project-card">
          <img src={telo_main} alt="project-image" className="project-image" />
          <img src={telo_chat} alt="project-image" className="project-image" />
        </div>
      </div>
    </div>
  );
}

export default Projects;
